function renderCompanionPreview(){
  const frame=$("#companionPreviewFrame");if(!frame)return;
  const settings=companionSettingsFromForm(),size=Math.max(176,Math.min(420,settings.size||280));
  frame.style.setProperty("--preview-size",`${size}px`);frame.className="companion-preview-frame";
  $("#companionPreviewSize").textContent=`${size} px`;
  const data={type:"companion-preview-state",state:companionPreviewState()};
  for(const selector of ["#companionPreview","#companionFullPreview"])$(selector)?.contentWindow?.postMessage(data,"*");
}
