async function saveCompanionSettings(event){event.preventDefault();try{const data=await api("save-companion-settings",companionSettingsFromForm());renderCompanionSettings(data);toast("Map Companion settings saved · the running overlay updates automatically")}catch(error){toast(error.message,true)}}
async function launchMapCompanion(event){const button=event?.currentTarget||$("#launchMapCompanionBtn"),label=button.textContent;button.disabled=true;button.textContent="Checking launcher…";setAppStatus("Checking Map Companion launcher…");try{const result=await api("launch-map-companion"),message=result.gameAlreadyRunning?"Map Companion attached · switching to Scrap Mechanic":"Scrap Mechanic is starting through Steam…";toast(message);setAppStatus(message)}catch(error){toast(error.message,true);setAppStatus("Map Companion could not start")}finally{button.textContent=label;setTimeout(()=>button.disabled=false,900)}}
async function applySettings(event){event.preventDefault();try{const data=await api("update-settings",{difficulty:Number($("#difficulty").value),multiplayer:Number($("#multiplayer").value),physicsQuality:Number($("#physicsQuality").value),seed:Number($("#seed").value),flags:Number($("#flags").value),gametick:Number($("#gametick").value)});state.current=data.current;updateDirty();toast("Settings applied in memory")}catch(error){toast(error.message,true)}}
function updateDirty(force){if(force)state.current.dirty=true;$("#dirtyBadge").classList.toggle("hidden",!state.current?.dirty)}
async function saveCopy(){if(!state.current)return;try{const data=await api("save-copy");toast(`Edited copy saved to the external backup archive: ${data.path}`);if(state.view==="backups")await loadBackups()}catch(error){toast(error.message,true)}}
async function overwrite(){if(!state.current)return;if(!confirm("Close Scrap Mechanic first. Save these changes to the game world? The untouched database will first be backed up outside the game's save folders."))return;try{const data=await api("overwrite",{confirmation:"OVERWRITE"});resetMapState();state.current=data.current;state.containers=data.containers;state.world=null;state.services=null;state.character=null;state.blueprints=null;state.unlocks.data=null;state.unlocks.generation++;renderSavePicker();renderContainers();renderSettings();updateLoadedState();await Promise.all([loadContainer(state.current.inventory_container_id||state.containers[0]?.id),loadWorldState()]);if(state.view==="unlocks")await loadUnlocksState();if(state.view==="character")await loadCharacterState();if(state.view==="blueprints")await loadBlueprintState();if(state.view==="map")await initMap();updateDirty();toast(`Saved · external backup: ${data.backup.path}`)}catch(error){toast(error.message,true)}}

function mapProjection(){if(!state.map.meta)return{mode:"topdown",width:0,height:0};if(state.map.mode==="isometric"&&state.map.native)return{mode:"isometric",width:state.map.native.width,height:state.map.native.height};return{mode:"topdown",width:state.map.meta.width,height:state.map.meta.height}}
function mapPixelToDisplay(point){if(state.map.mode!=="isometric"||!state.map.native)return point;const [xmin,,,ymax]=state.map.meta.bounds,native=state.map.native,worldX=xmin+point.x/state.map.meta.cellPixels,worldY=ymax-point.y/state.map.meta.cellPixels;return{x:(worldX-worldY)*native.cellWidth/2+native.originX,y:(worldX+worldY)*native.cellHeight/2+native.originY}}
function displayToMapPixel(point){if(state.map.mode!=="isometric"||!state.map.native)return point;const [xmin,,,ymax]=state.map.meta.bounds,native=state.map.native,isoX=(point.x-native.originX)/(native.cellWidth/2),isoY=(point.y-native.originY)/(native.cellHeight/2),worldX=(isoX+isoY)/2,worldY=(isoY-isoX)/2;return{x:(worldX-xmin)*state.map.meta.cellPixels,y:(ymax-worldY)*state.map.meta.cellPixels}}
