    const feature=group.points[0].feature,category=symbols.category(feature),cluster=group.points.length>1,marker=document.createElement("button");
    marker.type="button";marker.className=`marker waypoint-marker ${category}${cluster?" cluster":""}${feature.key===state.map.selectedFeature?.key?" selected":""}`;
    marker.style.left=`${group.x}px`;marker.style.top=`${group.y}px`;marker.style.setProperty("--marker-color",symbols.color(feature));
    if(cluster)marker.textContent=String(group.points.length);else marker.append(symbols.icon(feature,category==="player"?27:19));
    const label=cluster?`${group.points.length} nearby locations: ${group.points.map(p=>p.feature.label).join(", ")}`:feature.label;
    marker.setAttribute("aria-label",label);marker.title=cluster?label:"";
    marker.addEventListener("pointerdown",event=>event.stopPropagation());
    if(!cluster){marker.addEventListener("pointerenter",event=>showMapTooltip(event,feature));marker.addEventListener("pointermove",positionMapTooltip);marker.addEventListener("pointerleave",hideMapTooltip)}
