/* High-confidence profile and recovery editors */
function renderWorldState(){
  const world=state.world||{players:[],raids:[],progression:{},quests:{active:[],completed:[]},time:{},beacons:[]};const select=$("#playerStateSelect"),selected=Number(select.value||0);select.replaceChildren();
  world.players.forEach((player,index)=>{const option=document.createElement("option");option.value=index;option.textContent=player.steamId?`Player ${index+1} · ${player.steamId}`:`Player ${player.playerId}`;select.append(option)});if(world.players.length)select.value=String(Math.min(selected,world.players.length-1));renderSelectedPlayer();
  $("#raidCount").textContent=fmt(world.raids.length);$("#clearRaidsBtn").disabled=!world.raids.length;renderStateList($("#raidList"),world.raids.map(raid=>`Level ${raid.level||"?"} · World ${raid.worldId}${raid.position?` · ${raid.position.slice(0,2).map(value=>Number(value).toFixed(1)).join(", ")}`:""}`),"No active raids in this save.");
  const p=world.progression||{};$("#seedTier").value=p.seedTier??0;$("#vaultTotal").value=p.vaultTotal??0;$("#consoleUnlocked").checked=Boolean(p.consoleUnlocked);$("#beaconCrafted").checked=Boolean(p.beaconCrafted);$("#progressionForm").classList.toggle("unavailable",!p.available);$("#progressionInfo").textContent=`${fmt(p.completedGrowlabs)} growlabs completed · ${fmt(world.beaconCount)} player beacons`;
  renderStateList($("#activeQuestList"),(world.quests?.active||[]).map(quest=>quest.name),"No active quests.");renderStateList($("#completedQuestList"),(world.quests?.completed||[]).map(quest=>quest.name),"No completed quests.");
  const t=world.time||{};$("#worldDay").value=t.day??0;$("#worldHour").value=Number(t.hour||0).toFixed(2);$("#worldTimeProgress").checked=Boolean(t.progresses);$("#worldTimeForm").classList.toggle("unavailable",!t.available);
  $("#deathMarkerCount").textContent=`${fmt(world.deathMarkers)} deaths`;$("#clearDeathMarkersBtn").disabled=!world.deathMarkers;$("#aggroCreations").checked=Boolean(world.aggroCreations);renderBeaconEditor();updateWorldCapabilityControls()
}
function renderSelectedPlayer(){
  const player=state.world?.players?.[Number($("#playerStateSelect").value||0)],available=Boolean(player);$("#playerStatusForm").classList.toggle("unavailable",!available);$("#playerPerksForm").classList.toggle("unavailable",!available);$("#playerStatusForm button[type=submit]").disabled=!available;$("#playerPerksForm button[type=submit]").disabled=!available;
  if(!player){$("#playerIdentity").textContent="No editable player state is stored in this world mode.";return}
  $("#playerHp").value=editableNumber(player.hp);$("#playerMaxHp").value=editableNumber(player.maxHp);$("#playerBreath").value=editableNumber(player.breath);$("#playerMaxBreath").value=editableNumber(player.maxBreath);$("#playerConscious").checked=player.conscious;$("#playerRevival").checked=player.revivalItem;$("#playerIdentity").textContent=`Inventory #${player.inventoryContainerId??"—"} · Carry slot #${player.carryContainerId??"—"} · World ${player.worldId??"—"}`;
  const perks=new Set(player.perks||[]);$("#perkBonusHealth").checked=perks.has(1);$("#perkHammerSpeed").checked=perks.has(2);$("#perkFallProtection").checked=perks.has(3);$("#perkHighJump").checked=perks.has(4);
  const pos=player.position||[];$("#playerX").value=editableNumber(pos[0]);$("#playerY").value=editableNumber(pos[1]);$("#playerZ").value=editableNumber(pos[2]);const temporary=player.respawnPoints?.temporary,permanent=player.respawnPoints?.permanent;$("#teleportTemporaryBedBtn").disabled=!temporary?.position;$("#resetTemporaryBedBtn").disabled=!temporary;$("#teleportPermanentBedBtn").disabled=!permanent?.position;$("#respawnPointInfo").textContent=`Placed bed: ${temporary?.location||"none"} · Permanent bed: ${permanent?.location||"none"}${player.inOil||player.inChemical||player.respawnBlocked?" · A stuck-state flag is active":""}`;
  const bags=$("#deathBagList");bags.replaceChildren();if(!player.bags?.length){bags.innerHTML='<div class="state-list-empty">No saved death bags for this player.</div>'}else player.bags.forEach(bag=>{const row=document.createElement("div");row.className="state-list-item action-state-row";row.innerHTML=`<span>Death bag ${bag.index+1}${bag.position?` · ${bag.position.map(value=>Number(value).toFixed(1)).join(", ")}`:""}</span><button class="button ghost">Move to bag</button>`;row.querySelector("button").addEventListener("click",()=>teleportToBag(bag.index));bags.append(row)})
}
async function runWorldEdit(method,payload,message){try{const data=await api(method,payload);state.world=data.state;renderWorldState();updateDirty(true);toast(typeof message==="function"?message(data):message)}catch(error){toast(error.message,true)}}
async function applyPlayerPerks(event){event.preventDefault();const perks=[];if($("#perkBonusHealth").checked)perks.push(1);if($("#perkHammerSpeed").checked)perks.push(2);if($("#perkFallProtection").checked)perks.push(3);if($("#perkHighJump").checked)perks.push(4);await runWorldEdit("update-player-perks",{index:Number($("#playerStateSelect").value||0),perks},"Player perks staged")}
async function applyPlayerPosition(){await runWorldEdit("teleport-player",{index:Number($("#playerStateSelect").value||0),x:Number($("#playerX").value),y:Number($("#playerY").value),z:Number($("#playerZ").value)},"Player position staged")}
async function teleportToRespawn(kind){await runWorldEdit("teleport-to-respawn",{index:Number($("#playerStateSelect").value||0),kind},`Player moved to ${kind} respawn point`)}
async function teleportToBag(bagIndex){await runWorldEdit("teleport-to-bag",{index:Number($("#playerStateSelect").value||0),bagIndex},"Player moved to death bag")}
async function resetTemporaryBed(){if(!confirm("Forget this player's placed bed? The permanent location will become the respawn fallback."))return;await runWorldEdit("reset-temporary-bed",{index:Number($("#playerStateSelect").value||0)},"Placed bed forgotten")}
async function repairPlayer(){await runWorldEdit("repair-player",{index:Number($("#playerStateSelect").value||0)},"Chemical, oil and respawn-blocked flags cleared")}
async function applyCreationAggro(){await runWorldEdit("update-creation-aggro",{enabled:$("#aggroCreations").checked},"Creation aggro setting staged")}
async function clearDeathMarkers(){if(!confirm(`Clear ${fmt(state.world?.deathMarkers)} stored death markers?`))return;await runWorldEdit("clear-death-markers",{},data=>`${fmt(data.removed)} death markers cleared`)}
function beaconGlyph(index,color="#fff",interactive=false){const visuals=state.world?.beaconVisuals||{},node=document.createElement(interactive?"button":"span"),size=interactive?34:42;node.className=`beacon-glyph${interactive?" selectable":""}`;node.title=`Beacon symbol ${index+1}`;node.style.backgroundColor=color;if(visuals.atlas){const scale=size/Number(visuals.frame||132),x=(12+144*index)*scale,w=Number(visuals.width||3468)*scale,h=Number(visuals.height||132)*scale;node.style.webkitMaskImage=`url("${visuals.atlas}")`;node.style.maskImage=`url("${visuals.atlas}")`;node.style.webkitMaskSize=`${w}px ${h}px`;node.style.maskSize=`${w}px ${h}px`;node.style.webkitMaskPosition=`-${x}px 0`;node.style.maskPosition=`-${x}px 0`}return node}
function renderBeaconEditor(){const root=$("#beaconEditorList"),beacons=state.world?.beacons||[],visuals=state.world?.beaconVisuals||{},colors=visuals.colors||[];root.replaceChildren();$("#beaconEditorCount").textContent=fmt(beacons.length);if(!beacons.length){root.innerHTML='<div class="state-list-empty">No player beacons stored in this save.</div>';return}beacons.forEach(beacon=>{const row=document.createElement("div");row.className="beacon-editor-row visual-beacon-row";let selectedIcon=Math.max(0,Math.min(23,Number(beacon.iconIndex)||0)),selectedColor=Math.max(1,Math.min(8,Number(beacon.colorIndex)||1));const info=document.createElement("div");info.innerHTML=`<strong>Beacon #${escapeHtml(beacon.id)}</strong><small>${beacon.position?beacon.position.map(value=>Number(value).toFixed(1)).join(", "):"Position unavailable"}${beacon.linked?"":" · physical storage not linked"}</small>`;const preview=document.createElement("div");preview.className="beacon-current-preview";const refresh=()=>{preview.replaceChildren(beaconGlyph(selectedIcon,colors[selectedColor-1]||"#fff"));iconGrid.querySelectorAll("button").forEach((button,index)=>button.classList.toggle("selected",index===selectedIcon));colorGrid.querySelectorAll("button").forEach((button,index)=>button.classList.toggle("selected",index+1===selectedColor))};const picker=document.createElement("details");picker.className="beacon-visual-picker";const summary=document.createElement("summary");summary.textContent="Choose icon & color";const iconGrid=document.createElement("div");iconGrid.className="beacon-icon-grid";for(let index=0;index<24;index++){const button=beaconGlyph(index,"#fff",true);button.type="button";button.addEventListener("click",()=>{selectedIcon=index;refresh()});iconGrid.append(button)}const colorGrid=document.createElement("div");colorGrid.className="beacon-color-grid";colors.forEach((color,index)=>{const button=document.createElement("button");button.type="button";button.title=`Color ${index+1}`;button.style.background=color;button.addEventListener("click",()=>{selectedColor=index+1;refresh()});colorGrid.append(button)});picker.append(summary,iconGrid,colorGrid);const apply=document.createElement("button");apply.className="button ghost";apply.textContent="Apply";apply.disabled=!beacon.linked;apply.addEventListener("click",()=>updateBeacon(beacon.id,selectedIcon,selectedColor));row.append(info,preview,picker,apply);root.append(row);refresh()})}
async function updateBeacon(id,iconIndex,colorIndex){await runWorldEdit("update-beacon",{id,iconIndex,colorIndex},`Beacon #${id} updated`)}

async function loadWorldServices(){try{state.services=await api("world-services-state");renderWorldServices()}catch(error){toast(error.message,true)}}
function weatherSymbol(name){const lower=String(name).toLowerCase();if(lower.includes("thunder"))return "⚡";if(lower.includes("rain"))return "☂";if(lower.includes("drizzle"))return "☔";if(lower.includes("clear"))return "☀";return "☁"}
function renderWorldServices(){
  const data=state.services||{},weather=data.weather||{},tornadoes=data.tornadoes||{};
  $("#weatherQueueCount").textContent=`${fmt(weather.queue?.length)} periods · ${fmt(weather.days?.length)} days`;
  const timeline=$("#weatherTimeline");timeline.replaceChildren();
  (weather.days||[]).forEach((day,dayIndex)=>{
    const group=document.createElement("div");group.className="weather-day";
    group.innerHTML=`<small>${dayIndex===0?"CURRENT DAY":`DAY ${dayIndex+1}`}</small>`;
    const periods=document.createElement("div");periods.className="weather-periods";
    day.forEach((condition,periodIndex)=>{
      const queueIndex=dayIndex*4+periodIndex,tile=document.createElement("button");
      tile.type="button";tile.className=`weather-period weather-${String(condition).toLowerCase()}`;
      tile.title=`Edit day ${dayIndex+1}, period ${periodIndex+1}`;
      tile.innerHTML=`<small>PERIOD ${periodIndex+1}</small><span>${weatherSymbol(condition)}</span><strong>${escapeHtml(condition.replace(/([a-z])([A-Z])/g,"$1 $2"))}</strong>`;
      const edit=event=>{event.preventDefault();openWeatherPeriod(queueIndex,condition)};
      tile.addEventListener("click",edit);tile.addEventListener("contextmenu",edit);periods.append(tile);
    });
    group.append(periods);timeline.append(group);
  });
  if(!weather.queue?.length)timeline.innerHTML='<div class="state-list-empty">No periods are saved yet. Add a future day to create the forecast.</div>';
  $("#addWeatherDayBtn").disabled=!weather.available||(weather.queue?.length||0)>=120;
  $("#advanceWeatherBtn").disabled=!weather.available||!weather.queue?.length;
  $("#tornadoSavedCount").textContent=`${fmt(tornadoes.visitedCells)} cells`;$("#tornadoObjectCount").textContent=fmt(tornadoes.saved);$("#tornadoVisitedCount").textContent=fmt(tornadoes.visitedCells);$("#tornadoNextId").textContent=fmt(tornadoes.nextId);$("#resetTornadoBtn").disabled=!tornadoes.available||(!tornadoes.saved&&!tornadoes.visitedCells);$("#registeredWorldCount").textContent=fmt(data.worlds?.length);renderStateList($("#registeredWorldList"),(data.worlds||[]).map(world=>`${world.name} · World ${world.worldId??"reference unavailable"}`),"No registered world service entries were found.")
}
function openWeatherPeriod(index,condition){
  const weather=state.services?.weather||{},day=Math.floor(index/4)+1,period=index%4+1,select=$("#weatherPeriodCondition");
  select.replaceChildren();(weather.conditions||[]).forEach(item=>{const option=document.createElement("option");option.value=item.id;option.textContent=`${weatherSymbol(item.id)} ${item.name}${item.rain?` · ${Math.round(item.rain*100)}% rain`:""}`;select.append(option)});
  $("#weatherPeriodIndex").value=String(index);$("#weatherPeriodTitle").textContent=`${day===1?"Current day":`Day ${day}`} · period ${period}`;select.value=condition;$("#weatherPeriodDialog").showModal();
}
async function runServiceEdit(method,payload,message){try{const data=await api(method,payload);state.services=data.state;renderWorldServices();updateDirty(true);toast(typeof message==="function"?message(data):message);return true}catch(error){toast(error.message,true);return false}}
async function applyWeatherPeriod(event){event.preventDefault();const index=Number($("#weatherPeriodIndex").value),condition=$("#weatherPeriodCondition").value;if(await runServiceEdit("set-weather-period",{index,condition},`Day ${Math.floor(index/4)+1}, period ${index%4+1} staged`))$("#weatherPeriodDialog").close()}
async function addWeatherDay(){await runServiceEdit("append-weather-day",{},data=>`Forecast day ${data.days} added; click a tile to customize it`)}
async function advanceWeatherDay(){await runServiceEdit("advance-weather-day",{},"Current forecast day skipped")}
async function resetTornadoService(){if(!confirm("Clear saved tornadoes and visited desert-cell cooldowns? New tornadoes can spawn when the world loads eligible desert cells."))return;await runServiceEdit("reset-tornado-service",{confirmation:"RESET TORNADOES"},data=>`${fmt(data.cleared.saved)} tornadoes and ${fmt(data.cleared.visited)} visited cells cleared`)}

async function loadCharacterState(){try{state.character=await api("character-state");renderCharacter()}catch(error){toast(error.message,true)}}
function renderCharacter(){const data=state.character,root=$("#characterSlotGrid");root.replaceChildren();if(!data?.available){root.innerHTML=`<div class="panel manager-empty">${escapeHtml(data?.error||"Character profile unavailable")}</div>`;return}$("#characterGender").value=String(data.gender);$("#characterProfilePath").textContent=data.path;$("#saveCharacterBtn").disabled=!data.dirty;data.slots.forEach(slot=>{const card=document.createElement("article");card.className="panel character-slot-card visual-character-card";const select=document.createElement("select");select.dataset.index=slot.index;select.innerHTML='<option value="">None</option>';if(slot.uuid&&!slot.options.some(option=>option.uuid===slot.uuid)){const current=document.createElement("option");current.value=slot.uuid;current.textContent=`${slot.selectedName} (current)`;select.append(current)}slot.options.forEach(option=>{const node=document.createElement("option");node.value=option.uuid;node.textContent=option.name;select.append(node)});select.value=slot.uuid||"";const palette=document.createElement("input");palette.type="number";palette.min="0";palette.max="255";palette.value=slot.palette;palette.dataset.palette=slot.index;select.addEventListener("change",stageCharacter);palette.addEventListener("change",stageCharacter);const header=document.createElement("div");header.className="character-card-header";header.append(clothingVisual({name:slot.selectedName||slot.name,icon:slot.icon}));const title=document.createElement("div");title.innerHTML=`<div class="eyebrow">SLOT ${slot.index+1}</div><h2>${escapeHtml(slot.name)}</h2><strong>${escapeHtml(slot.selectedName)}</strong><small>${escapeHtml(slot.selectedInternal||"")}</small>`;header.append(title);const controls=document.createElement("div");controls.className="character-slot-controls";const selectLabel=document.createElement("label");selectLabel.textContent="Item";selectLabel.append(select);const paletteLabel=document.createElement("label");paletteLabel.textContent="Palette index";paletteLabel.append(palette);controls.append(selectLabel,paletteLabel);card.append(header,controls);root.append(card)})}
async function stageCharacter(){if(!state.character?.available)return;const slots=state.character.slots.map(slot=>({uuid:$(`select[data-index="${slot.index}"]`).value,palette:Number($(`input[data-palette="${slot.index}"]`).value)}));try{const data=await api("update-character",{gender:Number($("#characterGender").value),slots});state.character=data.state;renderCharacter();toast("Character appearance staged; apply it when ready")}catch(error){toast(error.message,true)}}
async function saveCharacter(){if(!confirm("Apply this appearance to the global Scrap Mechanic character profile? The existing profile will be archived first."))return;try{const data=await api("save-character",{confirmation:"APPLY CHARACTER"});state.character=data.state;renderCharacter();toast(data.backup?`Character saved · backup: ${data.backup.path}`:"Character profile unchanged")}catch(error){toast(error.message,true)}}

async function loadBlueprintState(){try{state.blueprints=await api("blueprint-state");renderBlueprints()}catch(error){toast(error.message,true)}}
function renderBlueprints(){const data=state.blueprints,root=$("#blueprintGrid");root.replaceChildren();$("#blueprintSummary").textContent=`${fmt(data.blueprints.length)} local blueprints · archives: ${data.archiveRoot}`;if(!data.blueprints.length){root.innerHTML='<div class="panel manager-empty">No local blueprints found for this Steam user.</div>';return}data.blueprints.forEach(entry=>{const card=document.createElement("article");card.className="panel blueprint-card";card.innerHTML=`${entry.icon?`<img src="${escapeHtml(entry.icon)}" alt="">`:'<div class="blueprint-placeholder">▧</div>'}<div class="blueprint-card-body"><div class="eyebrow">${entry.fileId?"WORKSHOP BLUEPRINT":"LOCAL BLUEPRINT"}</div><h2>${escapeHtml(entry.name)}</h2><p>${escapeHtml(entry.description)}</p><small>${fmt(entry.bodies)} bodies · ${fmt(entry.joints)} joints · ${escapeHtml(entry.id)}</small></div><div class="manager-card-actions"><button data-action="edit" class="button primary">Edit</button><button data-action="duplicate" class="button ghost">Duplicate</button><button data-action="export" class="button ghost">Archive ZIP</button></div>`;card.querySelector('[data-action="edit"]').addEventListener("click",()=>openBlueprintEditor(entry));card.querySelector('[data-action="duplicate"]').addEventListener("click",()=>duplicateBlueprint(entry));card.querySelector('[data-action="export"]').addEventListener("click",()=>exportBlueprint(entry));root.append(card)})}
function openBlueprintEditor(entry){$("#blueprintDialogId").value=entry.id;$("#blueprintDialogTitle").textContent=entry.name;$("#blueprintName").value=entry.name;$("#blueprintDescription").value=entry.description;$("#blueprintDialog").showModal()}
async function saveBlueprintMetadata(event){event.preventDefault();try{const data=await api("rename-blueprint",{id:$("#blueprintDialogId").value,name:$("#blueprintName").value,description:$("#blueprintDescription").value,confirmation:"EDIT BLUEPRINT"});state.blueprints=data.state;$("#blueprintDialog").close();renderBlueprints();toast(`Blueprint updated · previous version archived at ${data.backup}`)}catch(error){toast(error.message,true)}}
async function duplicateBlueprint(entry){if(!confirm(`Duplicate “${entry.name}” as a new local blueprint?`))return;try{const data=await api("duplicate-blueprint",{id:entry.id,name:`${entry.name} copy`,confirmation:"DUPLICATE BLUEPRINT"});state.blueprints=data.state;renderBlueprints();toast("Blueprint duplicated")}catch(error){toast(error.message,true)}}
async function exportBlueprint(entry){try{const data=await api("export-blueprint",{id:entry.id});state.blueprints=data.state;renderBlueprints();toast(`Blueprint archived: ${data.path}`)}catch(error){toast(error.message,true)}}
async function importBlueprint(){try{const choice=await api("choose-blueprint-archive");if(!choice.path)return;if(!confirm(`Import this Blueprint archive?\n${choice.path}`))return;const data=await api("import-blueprint",{path:choice.path,confirmation:"IMPORT BLUEPRINT"});state.blueprints=data.state;renderBlueprints();toast("Blueprint imported with a new local ID")}catch(error){toast(error.message,true)}}

function escapeHtml(text){return String(text).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]))}
if(window.pywebview?.api)boot();else window.addEventListener("pywebviewready",boot,{once:true});
